export function useCommandPaletteCommands({
  onOpenSettings,
  onOpenFeed,
  onOpenArchive,
  onNewRecording,
  onImportHandwriting,
}: UseCommandPaletteCommandsArgs) {
  const [open, setOpen] = useState(false);
  const [inputValue, setInputValue] = useState("");

  const { selectedNotes, selectedFolders, activeNote, activeFolder } = useSelection(
    useShallow((state) => ({
      selectedNotes: state.selectedNotes,
      selectedFolders: state.selectedFolders,
      activeNote: state.activeNote,
      activeFolder: state.activeFolder,
    }))
  );
  const {
    tree,
    createNewNote,
    deleteNotes,
    deleteFolders,
    moveNotesToArchive,
    moveNotesToFolder,
    flattenIntoFeed,
    updateNoteMarkers,
    startRenameFolder,
    allNotePreviews,
  } = useNotesTree();
  const { theme, setTheme } = useAppearance(
    useShallow((state) => ({
      theme: state.theme,
      setTheme: state.setTheme,
    }))
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.code === "KeyK") {
        event.preventDefault();
        setOpen((prev) => !prev);
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, []);

  const noteTargets = useMemo(
    () =>
      selectedNotes.size > 0
        ? Array.from(selectedNotes)
        : activeNote
          ? [activeNote]
          : [],
    [selectedNotes, activeNote]
  );
  const folderTargets = Array.from(selectedFolders);
  const removableFolders = folderTargets.filter((path) => !isSystemFolder(path));
  const notesOutsideFeed = noteTargets.filter(
    (path) => getNoteParentPath(path) !== FEED_FOLDER_PATH
  );
  const canFlatten = removableFolders.length > 0 || notesOutsideFeed.length > 0;
  const allArchived =
    noteTargets.length > 0 && noteTargets.every((path) => allNotePreviews[path]?.isArchived);
  const allReviewed =
    noteTargets.length > 0 && noteTargets.every((path) => allNotePreviews[path]?.isReviewed);

  const allFolderPaths = useMemo(() => collectFolderPaths(tree), [tree]);

  // --- Terminal `mv` command -------------------------------------------------
        return "right";
      return null;
    };

    const focusPane = (pane: PaneId) => {
      if (pane === "folders") {
        focusNoScroll(foldersPanelRef.current);
        return;
      }
      if (pane === "middle") {
        if (!hasMiddlePane) {
          focusNoScroll(foldersPanelRef.current);
          return;
        }
        const settingsSection =
          appMode === "settings"
            ? middlePaneRef.current?.querySelector<HTMLElement>(
                ".settings-nav-row.is-selected"
              )
            : null;
        focusNoScroll(settingsSection || middlePaneRef.current);
        return;
      }
      const editorElement =
        appMode === "notes"
          ? rightPaneRef.current?.querySelector<HTMLElement>(
              ".tiptap-content[contenteditable='true']"
            ) || rightPaneRef.current
          : rightPaneRef.current;
      focusNoScroll(editorElement);
    };

    const handleGlobalKeyDown = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.repeat) return;
      const code = event.code;
      const isLockShortcut = code === "KeyL" && event.shiftKey;
      if (
        code !== "KeyT" &&
        code !== "KeyW" &&
        code !== "KeyK" &&
        code !== "KeyJ" &&
        code !== "KeyN" &&
        code !== "Backspace" &&
        code !== "Equal" &&
        code !== "Minus" &&
        code !== "Digit0" &&
        code !== "NumpadAdd" &&
        code !== "NumpadSubtract" &&
        code !== "Numpad0" &&
        !isLockShortcut
      )
        return;
      event.preventDefault();

      if (code === "Equal" || code === "NumpadAdd") {
        if (appMode === "notes") increaseEditorFontSize();
        return;
      }
      if (code === "Minus" || code === "NumpadSubtract") {
        if (appMode === "notes") decreaseEditorFontSize();
        return;
      }
      if (code === "Digit0" || code === "Numpad0") {
        if (appMode === "notes") resetEditorFontSize();
        return;
      }
      if (code === "KeyN") {
        void createNewNote();
        return;
      }
      if (isLockShortcut) {
        void lockAppNow();
        return;
      }
      if (code === "Backspace") {
        if (appMode === "notes") deleteSelectedNotes();
        return;
      }
      if (code === "KeyT") {
        const currentPane = getFocusedPane();
        setSidebarCollapsed((prev) => {
          const next = !prev;
          if (next) {
            if (currentPane === "folders" || currentPane === "middle")
              lastLeftPaneFocusRef.current = currentPane;
            requestAnimationFrame(() => focusPane("right"));
          } else {
            requestAnimationFrame(() => focusPane(lastLeftPaneFocusRef.current));
          }
          return next;
        });
        return;
      }
      if (code === "KeyW") {
        const navigationPane: "folders" | "middle" =
          appMode === "settings" ? "middle" : "folders";
        if (sidebarCollapsed && navigationPane === "folders") {
          setSidebarCollapsed(false);
          lastLeftPaneFocusRef.current = navigationPane;
          requestAnimationFrame(() => focusPane(navigationPane));
          return;
        }
        const currentPane = getFocusedPane();
        if (currentPane === "right") {
          lastLeftPaneFocusRef.current = navigationPane;
          focusPane(navigationPane);
        } else {
          focusPane("right");
        }
        return;
      }

      const panes: PaneId[] = sidebarCollapsed
        ? ["right"]
        : hasMiddlePane
          ? ["folders", "middle", "right"]
          : ["folders", "right"];
      const currentPane = getFocusedPane();
      const startPane =
        currentPane && panes.includes(currentPane)
          ? currentPane
          : hasMiddlePane
            ? "middle"
            : "folders";
      const delta = code === "KeyK" ? 1 : -1;
      const nextIndex = Math.max(
        0,
        Math.min(panes.length - 1, panes.indexOf(startPane) + delta)
      );
      const targetPane = panes[nextIndex];
      if (targetPane === "folders" || targetPane === "middle")
        lastLeftPaneFocusRef.current = targetPane;
      focusPane(targetPane);
    };

    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [
    appMode,
    createNewNote,
    deleteSelectedNotes,
    decreaseEditorFontSize,
    foldersPanelRef,
    increaseEditorFontSize,
    middlePaneRef,
    resetEditorFontSize,
    rightPaneRef,
    lockAppNow,
    setSidebarCollapsed,
    shouldNestNotesInNavigation,
    sidebarCollapsed,
    lastLeftPaneFocusRef,
  ]);
}

  // -- Folders/Feed pane keyboard handler. Both tabs walk the same flat
  // visible-rows list; only where a "folder" selection lands differs (a real
  // folder vs. the Feed pseudo-folder plus a feed group).
  const handleFoldersKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const target = event.target as HTMLElement | null;
      if (
        target?.matches("input, textarea, select, [contenteditable='true']")
      ) {
        return;
      }

      if (event.key === "Tab" && !event.metaKey && !event.ctrlKey && !event.altKey) {
        event.preventDefault();
        if (activeNavigationTab === "feed") {
          openFoldersTab();
        } else {
          openFeedTab();
        }
        requestAnimationFrame(() => focusNoScroll(foldersPanelRef.current));
        return;
      }

      if ((event.metaKey || event.ctrlKey) && event.key === "ArrowRight") {
        event.preventDefault();
        if (appMode === "notes" && shouldNestNotesInNavigation) {
          const editorElement =
            rightPaneRef.current?.querySelector<HTMLElement>(
              ".tiptap-content[contenteditable='true']"
            ) || rightPaneRef.current;
          focusNoScroll(editorElement);
        } else {
          lastLeftPaneFocusRef.current = "middle";
          focusNoScroll(middlePaneRef.current);
        }
        return;
      }
      const code = event.code;
      const isPlainKey = !event.metaKey && !event.ctrlKey && !event.altKey;
      const navigationKey: NavigationKey | null =
        event.key === "ArrowUp" || (isPlainKey && code === "KeyK")
          ? "ArrowUp"
          : event.key === "ArrowDown" || (isPlainKey && code === "KeyJ")
            ? "ArrowDown"
            : event.key === "ArrowLeft"
              ? "ArrowLeft"
              : event.key === "ArrowRight"
                ? "ArrowRight"
                : null;
      const isVimCollapse = isPlainKey && code === "KeyH";
      const isVimExpand = isPlainKey && code === "KeyL";
      const isEnter = isPlainKey && event.key === "Enter";
      if (!navigationKey && !isVimCollapse && !isVimExpand && !isEnter) return;

      const isFeed = activeNavigationTab === "feed";
      const items = isFeed ? feedVisibleNavigationItems : visibleNavigationItems;
      if (items.length === 0) return;
      event.preventDefault();

      const itemIds = items.map((item) => item.id);
      const currentId = [
        lastSelectedNote,
        lastSelectedFolder,
        activeNote,
        isFeed ? activeFeedGroup : activeFolder,
      ].find((id) => Boolean(id && itemIds.includes(id))) ?? itemIds[0];
      const currentItem = items.find((item) => item.id === currentId);

      const focusPanel = () => focusNoScroll(foldersPanelRef.current);
      const focusEditor = () => {
        const editorElement =
          rightPaneRef.current?.querySelector<HTMLElement>(
            ".tiptap-content[contenteditable='true']"
          ) || rightPaneRef.current;
        focusNoScroll(editorElement);
  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen)
  const open = openProp ?? _open
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value
      if (setOpenProp) {
        setOpenProp(openState)
      } else {
